#!/usr/bin/env node
/** Build the small CommonJS client factory. No external UI packages or compiler. */
'use strict'
const { readFileSync, writeFileSync, mkdirSync } = require('node:fs')
const { join } = require('node:path')
const root = join(__dirname, '..', '..')
const modules = ['locale.cjs', 'styles.cjs', 'index.cjs']
const parts = [
  '/** Generated by src/client/build.cjs. */',
  'window.__ModuleLoader__.load({',
  '  id: "dsh-team-model-policy",',
  '  factory: (require) => {',
  '    const modules = {}, cache = {}',
  '    function localRequire(name) {',
  '      if (!name.startsWith("./")) return require(name)',
  '      const id = name.slice(2)',
  '      if (!cache[id]) { const module = { exports: {} }; cache[id] = module; modules[id](module, module.exports, localRequire) }',
  '      return cache[id].exports',
  '    }',
]
for (const name of modules) {
  parts.push('    modules[' + JSON.stringify(name) + '] = (module, exports, require) => {')
  parts.push(readFileSync(join(__dirname, name), 'utf8').replace(/\r\n/g, '\n').trimEnd().split('\n').map(line => line ? '      ' + line : '').join('\n'))
  parts.push('    }')
}
parts.push('    return localRequire("./index.cjs")', '  },', '})', '')
const generated = parts.join('\n'), target = join(root, 'lib', 'client.js')
if (process.argv.includes('--check')) {
  if (readFileSync(target, 'utf8') !== generated) { console.error('Client artifact is stale; run node src/client/build.cjs'); process.exitCode = 1 }
  else console.log('Client artifact matches source')
} else {
  mkdirSync(join(root, 'lib'), { recursive: true }); writeFileSync(target, generated)
  console.log('Wrote client artifact (' + Buffer.byteLength(generated) + ' bytes)')
}
